class HeaderManager{constructor(){this.header=document.querySelector(".main-header"),this.mobileMenuToggle=document.querySelector(".mobile-menu-toggle"),this.mobileNavigation=document.querySelector(".mobile-navigation"),this.body=document.body,this.init()}init(){this.setupScrollEffect(),this.setupMobileMenu(),this.setupActiveNavigation(),this.setupSidebarMobileMenu()}setupSidebarMobileMenu(){const e=document.querySelector(".sidebar-menu-toggle"),t=document.querySelector(".sidebar-mobile-navigation");if(!e||!t)return;e.addEventListener("click",()=>{const i="true"===e.getAttribute("aria-expanded");e.setAttribute("aria-expanded",!i),t.hasAttribute("hidden")?t.removeAttribute("hidden"):t.setAttribute("hidden","")});t.querySelectorAll("a").forEach(i=>{i.addEventListener("click",()=>{t.setAttribute("hidden",""),e.setAttribute("aria-expanded","false")})}),document.addEventListener("keydown",i=>{"Escape"!==i.key||t.hasAttribute("hidden")||(t.setAttribute("hidden",""),e.setAttribute("aria-expanded","false"))})}setupScrollEffect(){let e=0;window.addEventListener("scroll",()=>{const t=window.pageYOffset;t>50?this.header.classList.add("scrolled"):this.header.classList.remove("scrolled"),e=t})}setupMobileMenu(){if(!this.mobileMenuToggle||!this.mobileNavigation)return;this.mobileMenuToggle.addEventListener("click",()=>{this.toggleMobileMenu()});this.mobileNavigation.querySelectorAll("a").forEach(e=>{e.addEventListener("click",()=>{this.closeMobileMenu()})}),document.addEventListener("keydown",e=>{"Escape"===e.key&&null===this.mobileNavigation.getAttribute("hidden")&&this.closeMobileMenu()})}toggleMobileMenu(){"true"===this.mobileMenuToggle.getAttribute("aria-expanded")?this.closeMobileMenu():this.openMobileMenu()}openMobileMenu(){this.mobileMenuToggle.setAttribute("aria-expanded","true"),this.mobileMenuToggle.setAttribute("aria-label","Stäng meny"),this.mobileNavigation.removeAttribute("hidden"),this.body.style.overflow="hidden"}closeMobileMenu(){this.mobileMenuToggle.setAttribute("aria-expanded","false"),this.mobileMenuToggle.setAttribute("aria-label","Öppna meny"),this.mobileNavigation.setAttribute("hidden",""),this.body.style.overflow=""}setupActiveNavigation(){const e=window.location.pathname;document.querySelectorAll(".navigation a, .mobile-navigation a").forEach(t=>{const i=new URL(t.href).pathname;(e===i||e.endsWith("/")&&i===e+"index.html"||i.endsWith("/")&&e===i+"index.html")&&t.classList.add("active")})}}document.addEventListener("DOMContentLoaded",()=>{new HeaderManager});